import java.io.*;
import java.net.*;
import java.net.http.*;
import java.nio.file.*;

/** Opponent-only decisions, exact-once payout, and actual liveness expiry. */
public final class Departure631Check {
 static String base;static final HttpClient HTTP=HttpClient.newHttpClient();interface Writer{void write(DataOutputStream out)throws Exception;}
 static void ok(boolean b,String s){if(!b)throw new AssertionError(s);System.out.println("PASS: "+s);}
 static DataInputStream call(String token,String op,Writer body)throws Exception{ByteArrayOutputStream bytes=new ByteArrayOutputStream();DataOutputStream out=new DataOutputStream(bytes);out.writeInt(GunnyServer.MAGIC);out.writeUTF(op);if(body!=null)body.write(out);HttpRequest.Builder req=HttpRequest.newBuilder(URI.create(base+"/api")).header("X-Gunny-Client","3").header("X-Gunny-Features","departures");if(token!=null)req.header("Authorization","Bearer "+token);byte[] response=HTTP.send(req.POST(HttpRequest.BodyPublishers.ofByteArray(bytes.toByteArray())).build(),HttpResponse.BodyHandlers.ofByteArray()).body();DataInputStream in=new DataInputStream(new ByteArrayInputStream(response));if(in.readUnsignedByte()!=0)throw new IOException(in.readUTF());return in;}
 static void rejected(String token,int event)throws Exception{boolean rejected=false;try{call(token,"departure",o->{o.writeInt(event);o.writeBoolean(true);});}catch(IOException e){rejected=true;}ok(rejected,"Unauthorized or repeated departure choice rejected");}
 public static void main(String[] args)throws Exception{CloudStore.Memory store=new CloudStore.Memory();for(int i=0;i<6;i++)store.register("p"+i+"@departure.test","test-password-123","Người "+i);try(GunnyServer server=new GunnyServer(new InetSocketAddress("127.0.0.1",0),Path.of("backend/assets"),store)){base="http://127.0.0.1:"+server.port();String[] t=new String[6];for(int i=0;i<6;i++){int index=i;t[i]=call(null,"login",o->{o.writeUTF("p"+index+"@departure.test");o.writeUTF("test-password-123");}).readUTF();}
 int id=call(t[0],"quick",o->o.writeByte(2)).readInt();GunnyServer.Room room=server.rooms.get(id);for(int i=1;i<6;i++){int team=i%2;call(t[i],"join",o->{o.writeInt(id);o.writeByte(team);o.writeUTF("");});call(t[i],"ready",o->o.writeBoolean(true));}synchronized(room){room.start();room.phase=1;}call(t[2],"leave",null);ok(room.departurePending&&(room.leftMask&4)!=0,"Departure recorded for the real six-player seat");int event=room.departureVersion;rejected(t[0],event);ok(!room.battle.over,"A teammate cannot claim victory from their own teammate leaving");int timer=room.battle.countdown;for(int tick=0;tick<30;tick++)synchronized(room){room.tick();}ok(room.battle.countdown==timer,"Server countdown is frozen during the decision");call(t[1],"departure",o->{o.writeInt(event);o.writeBoolean(true);});ok(room.phase==2&&room.battle.winner==1,"Opposing team may finish with a server-confirmed victory");long end=System.currentTimeMillis()+3000;while(!room.settled&&System.currentTimeMillis()<end)Thread.sleep(20);ok(room.settled,"Departure win saved for six participants");for(int i=0;i<6;i++)ok(store.profile(server.sessions.get(t[i]).id).coins==(i%2==1?1000:0),"Correct reward for participant "+i);rejected(t[3],event);ok(store.profile(server.sessions.get(t[1]).id).coins==1000,"Repeated decision cannot grant another win payout");
 int solo=call(t[0],"quick",o->o.writeByte(1)).readInt();call(t[1],"quick",o->o.writeByte(1));GunnyServer.Room pair=server.rooms.get(solo);synchronized(pair){pair.start();pair.phase=1;}server.sessions.get(t[1]).lastSeen=System.currentTimeMillis()-46000;server.tick();ok(pair.departurePending&&pair.members[1]==null,"45-second silent disconnect creates the same departure choice");int secondEvent=pair.departureVersion;call(t[0],"departure",o->{o.writeInt(secondEvent);o.writeBoolean(false);});synchronized(pair){pair.battle.active=1;pair.tick();}ok(!pair.departurePending&&!pair.battle.humanTurn()&&!pair.battle.over,"Continue resumes AI for a departed actor, including unit one");
 synchronized(pair){pair.battle.active=0;pair.battle.ballCount=pair.battle.bursts=pair.battle.settle=0;pair.battle.units[0].angle=45;}int packetTurn=pair.battle.turn;call(t[0],"sync",o->{o.writeInt(0);o.writeByte(0);o.writeBoolean(true);o.writeInt(packetTurn);o.writeBoolean(false);o.writeInt(0);o.writeByte(1);o.writeInt(1);o.writeByte(6);o.writeShort(16*3+4);});ok(pair.battle.units[0].angle==45,"Delayed pre-departure input cannot act after the Continue choice");call(t[0],"sync",o->{o.writeInt(0);o.writeByte(0);o.writeBoolean(true);o.writeInt(packetTurn);o.writeBoolean(false);o.writeInt(pair.departureVersion);o.writeByte(1);o.writeInt(2);o.writeByte(6);o.writeShort(16*3+4);});ok(pair.battle.units[0].angle>45,"New input after Continue is accepted in order");
 call(t[0],"leave",null);int third=call(t[0],"quick",o->o.writeByte(1)).readInt();call(t[1],"quick",o->o.writeByte(1));GunnyServer.Room hostLeft=server.rooms.get(third);synchronized(hostLeft){hostLeft.start();hostLeft.phase=1;}call(t[0],"leave",null);int thirdEvent=hostLeft.departureVersion;call(t[1],"departure",o->{o.writeInt(thirdEvent);o.writeBoolean(false);});synchronized(hostLeft){hostLeft.battle.active=0;hostLeft.tick();}ok(!hostLeft.battle.humanTurn()&&!hostLeft.battle.units[0].human,"Departed host in unit zero also becomes AI, without a stuck turn");

 int fourth=call(t[0],"quick",o->o.writeByte(1)).readInt();call(t[1],"quick",o->o.writeByte(1));GunnyServer.Room completed=server.rooms.get(fourth);synchronized(completed){completed.start();completed.phase=1;completed.battle.over=true;completed.battle.winner=0;}call(t[0],"leave",null);ok(completed.phase==2&&!completed.departurePending&&completed.battle.winner==0,"Leaving after a decided battle cannot reverse its winner");

 }System.out.println("All 6.3.1 server departure checks passed");}
}
